#ifndef AS5048B_USER_BLOCK_DECL
#define AS5048B_USER_BLOCK_DECL

#include <Wire.h>

#define AS5048B_REG_ANGLE 0xFE

static bool as5048b_initialized[4] = {false, false, false, false};
static double as5048b_prev_deg[4] = {0.0, 0.0, 0.0, 0.0};
static double as5048b_total_deg[4] = {0.0, 0.0, 0.0, 0.0};

#endif

parameters.init_code:
Wire.begin();
for (int i = 0; i < 4; i++) {
    as5048b_initialized[i] = false;
    as5048b_prev_deg[i] = 0.0;
    as5048b_total_deg[i] = 0.0;
}

parameters.step_code:
// 入力ポート0番(inputs[0])からI2Cアドレスを取得 (例: 64 -> 0x40)
uint8_t addr = (uint8_t)inputs[0];

// 0x40〜0x43 以外の不正な値が来たら何もしない
if (addr < 0x40 || addr > 0x43) {
    outputs[0] = 0.0f;
    return;
}

// 配列のインデックス (0〜3) を計算
uint8_t idx = addr - 0x40;

uint8_t highByte = 0;
uint8_t lowByte = 0;

// 指定されたアドレスのAS5048Bから2バイト読み出し
Wire.beginTransmission(addr);
Wire.write(AS5048B_REG_ANGLE);
Wire.endTransmission(false);

Wire.requestFrom(addr, (uint8_t)2);
if (Wire.available() >= 2) {
    highByte = Wire.read();
    lowByte  = Wire.read();
}

// 14ビット合成・角度変換 [0 ~ 360 deg]
uint16_t raw_angle = ((uint16_t)highByte << 6) | (lowByte & 0x3F);
double current_deg = (double)raw_angle * 360.0 / 16384.0;

// インデックス(idx)ごとに360度またぎ補正・積算
if (!as5048b_initialized[idx]) {
    as5048b_prev_deg[idx] = current_deg;
    as5048b_total_deg[idx] = 0.0;
    as5048b_initialized[idx] = true;
} else {
    double diff = current_deg - as5048b_prev_deg[idx];

    if (diff < -180.0) {
        diff += 360.0;
    } else if (diff > 180.0) {
        diff -= 360.0;
    }

    as5048b_total_deg[idx] += diff;
    as5048b_prev_deg[idx] = current_deg;
}

// 出力ポート0番(outputs[0])へ代入
outputs[0] = (float)as5048b_total_deg[idx];

